// Alpine.js component + store registration.
// Bundled into alpine-init.min.js, loaded BEFORE alpine.min.js so every
// component/store is registered by the time 'alpine:init' fires.
// Generated by splitting the former specivo.js monolith — edit the component
// files under ./components/ and ./stores.js, then re-run `npm run build`.
