  Alpine.data('adminProjects', adminProjects);
  Alpine.data('versionIssues', versionIssues);
  Alpine.data('adminVersions', adminVersions);
  Alpine.data('wikiForm', wikiForm);
  Alpine.data('resolveThread', resolveThread);
  Alpine.data('watcherToggle', watcherToggle);
  Alpine.data('timeLogForm', timeLogForm);
  Alpine.data('relationForm', relationForm);
  Alpine.data('attachmentForm', attachmentForm);
  Alpine.data('journalReactions', journalReactions);
  Alpine.data('wikiAttachments', wikiAttachments);
  Alpine.data('issueAttachments', issueAttachments);
  Alpine.data('testEmailForm', testEmailForm);
  Alpine.data('sprintEdit', sprintEdit);
  Alpine.data('assigneePicker', assigneePicker);
  Alpine.data('backlogPage', backlogPage);
  Alpine.data('sprintComplete', sprintComplete);
